			if err := f.db.QueryRowContext(f.ctx, `SELECT version_id FROM resource_version_pins WHERE run_id=$1 AND flow_path='.' AND event_name='root.ready'`, changedRunID).Scan(&changedVersion); err != nil {
				t.Fatal(err)
			}
			owner, _ := deploymentForkOwner(t, f)
			forkServer := deploymentForkServer(t, f, owner)
			params := map[string]any{"source_run_id": sourceRunID, "bundle_hash": f.runtime.sourceArtifactFact.BundleHash(), "allow_source_freeze": true, "idempotency_key": uuid.NewString(), "data_pin_overrides": []any{map[string]any{"declaration": map[string]any{"flow_path": ".", "event": selectedDeploymentEvent}, "version_id": changedVersion}}}
